Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest")

	set accessToken=""
	set pRequest=""	
	$$$TRACE("Service Scope...["_..ServiceScope_"]") 
	set isAuth=##class(%SYS.OAuth2.AccessToken).IsAuthorized(..OAuth2ClientName,,..ServiceScope,.accessToken,.idtoken,.responseProperties,.error)

    if $isobject(error) {       
       $$$TRACE("IsAuthorized check failed...")
       Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).CheckError(..%ConfigName,"IsAuthorized check failed...Unable to get AccessToken.")		
    }   
    else {
	  $$$TRACE("Returned access_token: "_accessToken)    
    }  
    if isAuth=0 {
       $$$TRACE("Get new access_token...") 
       set tSC=##class(%SYS.OAuth2.Authorization).GetAccessTokenClient(..OAuth2ClientName, ..ServiceScope,.responseProperties,.error)
       set isAuth=##class(%SYS.OAuth2.AccessToken).IsAuthorized(..OAuth2ClientName,,..ServiceScope,
                 .accessToken,.idtoken,.responseProperties,.error)
       $$$TRACE("Returned access_token: "_accessToken)                          
    }    
    if (accessToken '=""){
	    $$$TRACE(" Token received successfully!!! ")
	    Set tStream=##class(%GlobalBinaryStream).%New()
		Set tSC=tStream.Write(accessToken)
		Set pResponse=##class(EnsLib.HTTP.GenericMessage).%New(tStream) 
	}else{
		Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).CheckError(..%ConfigName,"Unable to get AccessToken")		
	}
    quit tSC
